(p/'manage.html').write_text('''<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Portfolio Manager | Niya Gigs</title><link rel="stylesheet" href="extras.css"><script src="manage.js" defer></script></head><body class="extra-page"><header class="x-wrap x-nav"><a class="x-brand" href="index.html">NIYA <span>✳</span> GIGS</a><div class="x-links"><a href="index.html">Portfolio</a><a href="games.html">Games</a></div></header><main class="x-wrap"><section class="x-hero"><div class="x-kicker">PRIVATE WORKSPACE / LOCAL EDITOR</div><h1>YOUR WORK.<br><span class="x-gradient">YOUR CONTROL.</span></h1><p class="x-lead">Add a website, write its story and send it to your public portfolio without editing HTML. New entries are saved in this browser. Export the project data file and upload it to GitHub to publish them for everyone.</p></section><section class="x-panel" id="lock-panel"><h2>Unlock portfolio manager</h2><p class="x-muted">Enter your six-character access code.</p><form class="x-form" id="unlock-form"><label>ACCESS CODE<input id="access-code" type="password" maxlength="6" autocomplete="current-password" placeholder="6-character code" required></label><button class="x-btn" type="submit">UNLOCK WORKSPACE ↗</button><p class="x-status" id="lock-status" aria-live="polite"></p></form></section><section id="manager" class="x-hidden"><div class="x-stats"><div class="x-stat"><strong id="project-count">0</strong><small>PROJECTS SAVED HERE</small></div><div class="x-stat"><strong>JSON</strong><small>PORTABLE PUBLISH FILE</small></div><div class="x-stat"><strong>01</strong><small>NO CODE EDITING</small></div></div><div class="x-grid" style="grid-template-columns:1.15fr .85fr"><div class="x-panel"><div class="x-kicker">NEW CASE STUDY</div><h2>Add a website</h2><form class="x-form" id="project-form"><label>WEBSITE NAME<input name="name" maxlength="55" placeholder="e.g. Northstar Creative" required></label><label>SHORT DESCRIPTION<textarea name="description" maxlength="420" placeholder="What does the website do? What did you build?" required></textarea></label><label>PROJECT CATEGORY<select name="category"><option value="business">Business</option><option value="tools">Tools</option><option value="concept">Concept</option></select></label><label>LIVE WEBSITE URL<input name="url" type="url" placeholder="https://example.com" required></label><label>TECH / FEATURES<input name="tags" maxlength="140" placeholder="Responsive design, booking, dashboard"></label><label>YOUR ROLE<input name="role" maxlength="100" placeholder="Design and front-end development"></label><button class="x-btn" type="submit">SAVE WEBSITE ↗</button><p class="x-status" id="save-status" aria-live="polite"></p></form></div><div class="x-panel"><div class="x-kicker">PUBLISHING</div><h2>Take it live</h2><p class="x-muted">The manager cannot write directly into a GitHub Pages repository. Export your data, then add the downloaded file to the same folder as index.html in GitHub.</p><div class="x-toolbar"><button class="x-btn" id="export-btn">DOWNLOAD project-data.json</button><button class="x-btn secondary" id="logout-btn">LOCK MANAGER</button></div><label class="x-form">IMPORT A BACKUP<input type="file" id="import-file" accept="application/json"></label><p class="x-status" id="publish-status" aria-live="polite"></p><hr style="border-color:var(--xline);margin:24px 0"><h3>Saved on this device</h3><div id="saved-list" class="x-muted">No added projects yet.</div><p class="x-muted" style="font-size:12px">To remove an item, use its Remove button. Export again after making changes.</p></div></div><div class="x-panel"><h2>Important security note</h2><p class="x-muted">This static GitHub Pages version uses a simple front-end access gate. The code can be discovered by someone inspecting the site files, so it is a convenience lock, not strong authentication. Do not store private information here. For real account-level protection, connect a server-side login service such as Supabase Auth and restrict write access there.</p></div></section></main><footer class="x-wrap x-footer">NIYA GIGS · ERIC USHIE · PRIVATE WORKSPACE</footer></body></html>''')
(p/'manage.js').write_text(r'''const CODE='qwerty';const $=s=>document.querySelector(s);const KEY='niya-added-projects';let projects=[];try{projects=JSON.parse(localStorage.getItem(KEY)||'[]');if(!Array.isArray(projects))projects=[]}catch{projects=[]}function save(){localStorage.setItem(KEY,JSON.stringify(projects));render()}function render(){$('#project-count').textContent=projects.length;const list=$('#saved-list');list.replaceChildren();if(!projects.length){list.textContent='No added projects yet.';return}projects.forEach((p,i)=>{const row=document.createElement('div');row.style.cssText='display:flex;justify-content:space-between;gap:12px;align-items:center;border-bottom:1px solid var(--xline);padding:10px 0';const name=document.createElement('span');name.textContent=p.name;const del=document.createElement('button');del.className='x-btn secondary';del.textContent='Remove';del.addEventListener('click',()=>{projects.splice(i,1);save()});row.append(name,del);list.append(row)})}$('#unlock-form').addEventListener('submit',e=>{e.preventDefault();if($('#access-code').value===CODE){$('#lock-panel').classList.add('x-hidden');$('#manager').classList.remove('x-hidden');render()}else{$('#lock-status').textContent='That code did not match. Try again.';$('#access-code').value=''}});$('#project-form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget);const url=String(d.get('url')).trim();try{const u=new URL(url);if(!['http:','https:'].includes(u.protocol))throw Error()}catch{$('#save-status').textContent='Enter a valid website link starting with https://';return}projects.unshift({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),name:String(d.get('name')).trim(),description:String(d.get('description')).trim(),category:String(d.get('category')),url, tags:String(d.get('tags')).split(',').map(s=>s.trim()).filter(Boolean),role:String(d.get('role')).trim(),addedAt:new Date().toISOString()});save();e.currentTarget.reset();$('#save-status').textContent='Saved on this device. Export the JSON file to publish it.'});$('#export-btn').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(projects,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='project-data.json';a.click();URL.revokeObjectURL(a.href);$('#publish-status').textContent='Export created. Upload project-data.json beside index.html in GitHub.'});$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!Array.isArray(data)||data.some(p=>!p.name||!p.url||!p.description))throw Error();projects=data;save();$('#publish-status').textContent='Backup imported.'}catch{$('#publish-status').textContent='Could not import that file. Check that it is a valid project-data.json.'}e.target.value=''});$('#logout-btn').addEventListener('click',()=>{ $('#manager').classList.add('x-hidden');$('#lock-panel').classList.remove('x-hidden');$('#access-code').value=''});''')
