(p/'portfolio-extra.js').write_text(r'''const safeText=(tag,text,cls)=>{const el=document.createElement(tag);if(cls)el.className=cls;el.textContent=text;return el};async function loadAddedProjects(){let added=[];try{added=JSON.parse(localStorage.getItem('niya-added-projects')||'[]')}catch{}try{const r=await fetch('project-data.json',{cache:'no-store'});if(r.ok){const data=await r.json();if(Array.isArray(data))added=[...data,...added.filter(x=>!data.some(y=>y.id===x.id))]}}catch{}const grid=document.querySelector('#projects-grid');if(!grid)return;added.forEach((p,i)=>{if(!p||!p.name||!p.url||!p.description)return;const card=document.createElement('article');card.className='project-card';card.dataset.category=p.category||'business';card.dataset.search=[p.name,p.description,...(p.tags||[])].join(' ').toLowerCase();const art=document.createElement('div');art.className='project-art';art.style.cssText='background:linear-gradient(135deg,#172c50,#326b82);color:white;display:flex;flex-direction:column;justify-content:space-between;padding:22px';art.append(safeText('small','NIYA GIGS / PROJECT '+String(i+6).padStart(2,'0')));const title=safeText('strong',p.name);title.style.cssText='font:700 clamp(28px,4vw,43px)/1.05 Space Grotesk;max-width:85%';art.append(title,safeText('small','INDEPENDENT WEB PROJECT'));const body=document.createElement('div');body.className='project-body';const type=document.createElement('div');type.className='project-type';type.append(safeText('span',(p.category||'business').toUpperCase()+' / WEBSITE'),safeText('span',String(i+6).padStart(2,'0')));body.append(type,safeText('h3',p.name),safeText('p',p.description));const tags=document.createElement('div');tags.className='tag-row';(p.tags||[]).slice(0,4).forEach(t=>tags.append(safeText('span',t)));body.append(tags);const link=document.createElement('a');link.className='details-button';link.href=p.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='VISIT LIVE WEBSITE ↗';body.append(link);card.append(art,body);grid.append(card)});const total=grid.querySelectorAll('.project-card').length;const counter=document.querySelector('#project-total');if(counter)counter.innerHTML=total+' PROJECTS <b>✳</b>';document.querySelectorAll('.filter-button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.filter-button').forEach(x=>x.classList.remove('active'));b.classList.add('active')}));}
loadAddedProjects();function tick(){const now=new Date();const clock=document.querySelector('#live-clock'),date=document.querySelector('#live-date');if(clock)clock.textContent=new Intl.DateTimeFormat('en-NG',{timeZone:'Africa/Lagos',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true}).format(now);if(date)date.textContent=new Intl.DateTimeFormat('en-NG',{timeZone:'Africa/Lagos',weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(now)}tick();setInterval(tick,1000);async function weather(){const t=document.querySelector('#weather-temp'),d=document.querySelector('#weather-desc');if(!t)return;try{const r=await fetch('https://api.open-meteo.com/v1/forecast?latitude=6.5244&longitude=3.3792&current=temperature_2m,apparent_temperature,relative_humidity_2m,weather_code&timezone=Africa%2FLagos');if(!r.ok)throw Error();const j=await r.json(),c=j.current;const names={0:'Clear sky',1:'Mainly clear',2:'Partly cloudy',3:'Overcast',45:'Foggy',48:'Foggy',51:'Light drizzle',53:'Drizzle',55:'Heavy drizzle',61:'Light rain',63:'Rain',65:'Heavy rain',80:'Rain showers',81:'Rain showers',82:'Heavy showers',95:'Thunderstorm'};t.textContent=Math.round(c.temperature_2m)+'°C';d.textContent=(names[c.weather_code]||'Current conditions')+' · Feels like '+Math.round(c.apparent_temperature)+'°C · Lagos'}catch{t.textContent='Unavailable';d.textContent='Weather needs an internet connection.'}}weather();''')
