(p/'aurel-living.html').write_text('''<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AUREL Living — Objects for living</title><link rel="stylesheet" href="aurel.css"><script src="aurel.js" defer></script></head><body><header><a class="logo" href="aurel-living.html">AUREL<span>.</span></a><nav><a href="#collection">COLLECTION</a><a href="#story">OUR APPROACH</a><button id="cart-open">BAG <b id="cart-count">0</b></button></nav></header><main><section class="hero"><div><small>OBJECTS FOR LIVING / COLLECTION 01</small><h1>Make room<br>for <i>better living.</i></h1><p>Thoughtful pieces. Honest materials. A little more intention in every room.</p><a class="pill" href="#collection">EXPLORE THE COLLECTION ↘</a></div><div class="hero-art"><div class="sun"></div><div class="chair"><i></i><b></b><em></em></div><span>FORM / FUNCTION / FEELING</span></div></section><section id="collection" class="collection"><small>01 — THE COLLECTION</small><h2>Made to live with.</h2><div class="products" id="products"></div></section><section id="story" class="story"><small>02 — OUR APPROACH</small><h2>Less noise.<br><i>More meaning.</i></h2><p>AUREL is a fictional furniture-store concept created for the Niya Gigs portfolio. This demo explores product discovery and a simple shopping interaction.</p></section></main><dialog id="cart"><form method="dialog"><button class="close">×</button></form><small>YOUR BAG</small><h2>Selected pieces</h2><div id="cart-items"></div><p id="cart-total">Total: ₦0</p><button id="checkout" class="pill">PREPARE ENQUIRY ↗</button><p class="note">Demo only — no payment is collected.</p></dialog><footer>DESIGNED AS A NIYA GIGS CONCEPT · <a href="index.html">BACK TO PORTFOLIO ↗</a></footer></body></html>''')
